"""Exact fused dot product for a parameterized binary floating-point format.

All products and the accumulation are exact (big integers); only the final
sum is rounded once, in the requested mode, to the destination format.
"""
import json
import sys


def solve(req):
    ebits = req['ebits']
    fbits = req['fbits']
    mode = req['mode']
    pairs = req['pairs']

    width = 1 + ebits + fbits
    fmask = (1 << fbits) - 1
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    Eall = (1 << ebits) - 1
    emin = 1 - bias
    emax = Eall - 1 - bias
    sign_shift = ebits + fbits

    def decode(h):
        v = int(h, 16) & ((1 << width) - 1)
        s = v >> sign_shift
        e = (v >> fbits) & Eall
        f = v & fmask
        return s, e, f

    # ---- inspect every operand / classify every pair -------------------
    has_nan = False
    invalid = False
    inf_signs = set()

    for a_hex, b_hex in pairs:
        sa, ea, fa = decode(a_hex)
        sb, eb, fb = decode(b_hex)
        nan_a = (ea == Eall and fa != 0)
        nan_b = (eb == Eall and fb != 0)
        if nan_a:
            has_nan = True
            if not ((fa >> (fbits - 1)) & 1):
                invalid = True  # signaling NaN
        if nan_b:
            has_nan = True
            if not ((fb >> (fbits - 1)) & 1):
                invalid = True  # signaling NaN
        if nan_a or nan_b:
            # a NaN pair contributes no infinite product and never counts
            # as zero times infinity
            continue
        inf_a = (ea == Eall)
        inf_b = (eb == Eall)
        zero_a = (ea == 0 and fa == 0)
        zero_b = (eb == 0 and fb == 0)
        if (inf_a and zero_b) or (zero_a and inf_b):
            invalid = True  # zero times infinity, in either order
        elif inf_a or inf_b:
            inf_signs.add(sa ^ sb)  # infinite product

    if 0 in inf_signs and 1 in inf_signs:
        invalid = True  # both positive and negative infinite products

    def out(sign, e, f, flags):
        bits = (sign << sign_shift) | (e << fbits) | f
        return {'bits': format(bits, 'x'), 'flags': flags}

    if has_nan or invalid:
        # canonical NaN: sign 0, exponent Eall, only top fraction bit set
        return out(0, Eall, 1 << (fbits - 1), ['invalid'] if invalid else [])

    if inf_signs:
        sgn = inf_signs.pop()
        return out(sgn, Eall, 0, [])

    # ---- finite path: exact products and exact accumulation ------------
    prods = []  # (sign, magnitude, exponent)
    for a_hex, b_hex in pairs:
        sa, ea, fa = decode(a_hex)
        sb, eb, fb = decode(b_hex)
        if ea == 0:
            ma, pa = fa, emin - fbits
        else:
            ma, pa = F + fa, ea - bias - fbits
        if eb == 0:
            mb, pb = fb, emin - fbits
        else:
            mb, pb = F + fb, eb - bias - fbits
        prods.append((sa ^ sb, ma * mb, pa + pb))

    # negative zero for the exact sum only if every product is a negative
    # signed zero and there is at least one product
    all_neg_zero = bool(prods) and all(s == 1 and m == 0
                                       for (s, m, p) in prods)

    nonzero = [(s, m, p) for (s, m, p) in prods if m]
    if nonzero:
        pmin = min(p for (s, m, p) in nonzero)
        S = 0
        for (s, m, p) in nonzero:
            t = m << (p - pmin)
            S += -t if s else t

    if not nonzero or S == 0:
        # exact zero (no rounding, no flags)
        sgn = 1 if (mode == 'RDN' or all_neg_zero) else 0
        return out(sgn, 0, 0, [])

    sgn = 1 if S < 0 else 0
    mag = -S if S < 0 else S          # exact magnitude x = mag * 2**pmin
    L = mag.bit_length() - 1 + pmin   # floor(log2(x))
    Q = max(emin - fbits, L - fbits)  # quantum q = 2**Q
    d = Q - pmin
    if d <= 0:
        r = mag << (-d)               # x/q is an integer already
        rem = 0
        denom = 1
    else:
        r = mag >> d
        rem = mag & ((1 << d) - 1)
        denom = 1 << d

    if rem:
        twice = 2 * rem
        if mode == 'RNE':
            if twice > denom or (twice == denom and (r & 1)):
                r += 1
        elif mode == 'RNA':
            if twice >= denom:
                r += 1
        elif mode == 'RUP':
            if sgn == 0:
                r += 1
        elif mode == 'RDN':
            if sgn == 1:
                r += 1
        # RTZ: keep r

    # rounded magnitude value y = r * 2**Q
    y_log = None if r == 0 else (r.bit_length() - 1 + Q)

    if y_log is not None and y_log >= emax + 1:  # y >= 2**(emax+1)
        away = (mode in ('RNE', 'RNA')
                or (mode == 'RUP' and sgn == 0)
                or (mode == 'RDN' and sgn == 1))
        if away:
            return out(sgn, Eall, 0, ['overflow', 'inexact'])
        return out(sgn, Eall - 1, fmask, ['overflow', 'inexact'])

    flags = []
    inexact = rem != 0
    if inexact:
        flags.append('inexact')
        if y_log is None or y_log < emin:  # rounded magnitude below 2**emin
            flags.append('underflow')

    if r == 0:
        return out(sgn, 0, 0, flags)
    if y_log < emin:
        # subnormal: value = f * 2**(emin - fbits)
        f = r << (Q - emin + fbits)
        return out(sgn, 0, f, flags)
    e = y_log + bias
    M = r << (Q - y_log + fbits)   # significand in [F, 2*F)
    return out(sgn, e, M - F, flags)


def main():
    write = sys.stdout.write
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        req = json.loads(line)
        write(json.dumps(solve(req)) + '\n')


if __name__ == '__main__':
    main()
