"""Independent brute-force reference for small formats (rounding by candidate
search over all representable magnitudes), plus Fraction decoding."""
from fractions import Fraction


class Format:
    def __init__(self, ebits, fbits):
        self.ebits, self.fbits = ebits, fbits
        self.fmask = (1 << fbits) - 1
        self.bias = (1 << (ebits - 1)) - 1
        self.F = 1 << fbits
        self.Eall = (1 << ebits) - 1
        self.emin = 1 - self.bias
        self.emax = self.Eall - 1 - self.bias
        self.sign_shift = ebits + fbits
        self.width = 1 + ebits + fbits
        self.vmax = Fraction(2) ** (self.emax + 1)
        # all finite magnitudes, sorted
        vals = set()
        for e in range(0, self.Eall):
            for f in range(0, self.F):
                if e == 0:
                    v = Fraction(f) * Fraction(2) ** (self.emin - fbits)
                else:
                    v = Fraction(self.F + f) * Fraction(2) ** (e - self.bias - fbits)
                vals.add(v)
        self.vals = sorted(vals)  # distinct magnitudes incl. 0

    def decode(self, h):
        v = int(h, 16) & ((1 << self.width) - 1)
        s = v >> self.sign_shift
        e = (v >> self.fbits) & self.Eall
        f = v & self.fmask
        return s, e, f

    def value(self, h):
        """Return ('num', Fraction) | ('inf', sign) | ('qnan',None) | ('snan',None)"""
        s, e, f = self.decode(h)
        if e == self.Eall:
            if f == 0:
                return ('inf', s)
            return ('qnan' if (f >> (self.fbits - 1)) & 1 else 'snan', None)
        if e == 0:
            return ('num', Fraction((-1) ** s * f, 1) * Fraction(2) ** (self.emin - self.fbits))
        return ('num', Fraction((-1) ** s * (self.F + f), 1) * Fraction(2) ** (e - self.bias - self.fbits))

    def encode(self, sign, e, f):
        return format((sign << self.sign_shift) | (e << self.fbits) | f, 'x')

    def parity(self, val):
        """low stored fraction bit of the encoding of magnitude val (or virtual top)."""
        if val == self.vmax:
            return 0  # even significand 2**(fbits+1)
        # find encoding: subnormal or normal
        if val == 0:
            return 0
        e = 0
        # normal?
        L = val.numerator.bit_length() - 1  # val = num * 2**den_exp
        raise NotImplementedError

    def encode_val(self, val):
        """encoding (e,f) of an exactly representable finite magnitude"""
        assert val >= 0
        if val == 0:
            return 0, 0
        # val = m * 2**(emin-fbits) with integer m
        u = Fraction(2) ** (self.emin - self.fbits)
        m = val / u
        assert m.denominator == 1
        m = m.numerator
        if m < self.F:  # subnormal
            return 0, m
        b = m.bit_length() - 1
        M = m << (self.fbits - b)
        assert self.F <= M < 2 * self.F
        e = b + self.bias
        assert 1 <= e <= self.Eall - 1
        return e, M - self.F


def round_ref(fmt, x, sign, mode):
    """Round exact magnitude x (Fraction>0) in mode with result sign.
    Returns (bits, flags). Independent candidate-search implementation."""
    vals = fmt.vals
    import bisect
    i = bisect.bisect_left(vals, x)
    if i < len(vals) and vals[i] == x:
        e, f = fmt.encode_val(x)
        return fmt.encode(sign, e, f), []
    below = vals[i - 1] if i > 0 else None
    above = vals[i] if i < len(vals) else None
    if above is None or below is None or below < x <= fmt.vals[-1] and above is None:
        pass
    # if x above max finite, the 'above' candidate is the virtual overflow point
    if x > fmt.vals[-1]:
        below = fmt.vals[-1]
        above = None  # virtual
    assert below is not None
    bd = x - below
    ad = (above - x) if above is not None else (fmt.vmax - x)

    if mode == 'RTZ':
        pick_above = False
    elif mode == 'RUP':
        pick_above = (sign == 0)
    elif mode == 'RDN':
        pick_above = (sign == 1)
    elif mode == 'RNA':
        pick_above = not (bd < ad)  # tie -> away from zero (bigger magnitude)
    else:  # RNE
        if bd < ad:
            pick_above = False
        elif bd > ad:
            pick_above = True
        else:
            # tie -> even significand (low stored fraction bit 0)
            pb = fmt.encode_val(below)[1] & 1 if below > 0 else 0
            if above is not None:
                pa = fmt.encode_val(above)[1] & 1
            else:
                pa = 0  # virtual top is even
            pick_above = pa <= pb if pb != pa else True
            # if both parities equal (impossible for adjacent grid?) choose above? guard:
            if pb == pa:
                pick_above = True
    if pick_above and above is None:
        # overflow: y >= 2**(emax+1)
        away = (mode in ('RNE', 'RNA')
                or (mode == 'RUP' and sign == 0)
                or (mode == 'RDN' and sign == 1))
        if away:
            return fmt.encode(sign, fmt.Eall, 0), ['overflow', 'inexact']
        return fmt.encode(sign, fmt.Eall - 1, fmt.fmask), ['overflow', 'inexact']
    chosen = above if pick_above else below
    e, f = fmt.encode_val(chosen)
    flags = []
    if chosen != x:
        flags.append('inexact')
        if chosen < Fraction(2) ** fmt.emin:
            flags.append('underflow')
    return fmt.encode(sign, e, f), flags


def solve_ref(req):
    ebits, fbits, mode = req['ebits'], req['fbits'], req['mode']
    pairs = req['pairs']
    fmt = Format(ebits, fbits)
    has_nan = invalid = False
    inf_signs = set()
    parsed = []
    for a, b in pairs:
        va, vb = fmt.value(a), fmt.value(b)
        parsed.append((va, vb))
        for v in (va, vb):
            if v[0] == 'snan':
                invalid = True
                has_nan = True
            elif v[0] == 'qnan':
                has_nan = True
        if va[0] == 'nan' or vb[0] == 'nan' or va[0] in ('qnan', 'snan') or vb[0] in ('qnan', 'snan'):
            continue
        kinds = (va[0], vb[0])
        if ('inf' in kinds and 'zero' in kinds):
            pass
        # explicit classification
        def iszero(v):
            return v[0] == 'num' and v[1] == 0
        def isinf(v):
            return v[0] == 'inf'
        if (isinf(va) and iszero(vb)) or (iszero(va) and isinf(vb)):
            invalid = True
        elif isinf(va) or isinf(vb):
            inf_signs.add(va[1] ^ vb[1])
    if 0 in inf_signs and 1 in inf_signs:
        invalid = True
    if has_nan or invalid:
        return {'bits': fmt.encode(0, fmt.Eall, 1 << (fbits - 1)),
                'flags': ['invalid'] if invalid else []}
    if inf_signs:
        return {'bits': fmt.encode(inf_signs.pop(), fmt.Eall, 0), 'flags': []}
    # finite: exact products
    prods = []
    for va, vb in parsed:
        assert va[0] == 'num' and vb[0] == 'num'
        prods.append(va[1] * vb[1])
    all_neg_zero = bool(prods) and all(p == 0 for p in prods) and all(
        _prod_sign_neg(fmt, pairs[i][0], pairs[i][1]) for i in range(len(pairs)))
    total = sum(prods) if prods else Fraction(0)
    if total == 0:
        sgn = 1 if (mode == 'RDN' or all_neg_zero) else 0
        return {'bits': fmt.encode(sgn, 0, 0), 'flags': []}
    sign = 1 if total < 0 else 0
    bits, flags = round_ref(fmt, abs(total), sign, mode)
    return {'bits': bits, 'flags': flags}


def _prod_sign_neg(fmt, a, b):
    sa = fmt.decode(a)[0]
    sb = fmt.decode(b)[0]
    return (sa ^ sb) == 1
